\section*{Assumptions}
\begin{assumption}[Smoothness]\label{ass:smooth}
$f$ is $L$‑smooth, i.e.
\[
\forall w,u\in\RR^{d}:\quad 
f(u)\le f(w)+\inner{\nabla f(w)}{u-w}+\frac{L}{2}\norm{u-w}^{2}.
\]
\end{assumption}
\begin{assumption}[Lower Boundedness]\label{ass:lb}
$f$ is bounded below: $f^{\star}:=\inf_{w}f(w)>-\infty$.
\end{assumption}
\begin{assumption}[Unbiased Gradient]\label{ass:unbiased}
For all $t$, $\EE\!\left[g_t\mid w_t\right]=\nabla f(w_t)$.
\end{assumption}
\begin{assumption}[Bounded Variance]\label{ass:variance}
There exists $\sigma^{2}>0$ such that
\[
\EE\!\left[\norm{g_t-\nabla f(w_t)}^{2}\mid w_t\right]\le\sigma^{2},\qquad\forall t.
\]
\end{assumption}
\begin{assumption}[Step‑size Schedule]\label{ass:eta}
The schedule \eqref{eq:eta} satisfies $0\le\eta_t\le\eta_{\max}$ for all $t$ and
\[
\frac{1}{T}\sum_{t=0}^{T-1}\eta_t \;\ge\; \frac{\eta_{\max}}{2}.
\]
(Indeed the cosine annealing average over a full cycle equals $\eta_{\max}/2$.)
\end{assumption}

\section*{Main Convergence Theorem}
\begin{theorem}\label{thm:main}
Assume \ref{ass:smooth}–\ref{ass:eta} hold and run SGDR for $T$ iterations.  
Define the random iterate $w_{\tau}$ where $\tau$ is drawn uniformly from $\{0,\dots,T-1\}$. Then
\[
\EE\!\bigl[\norm{\nabla f(w_{\tau})}^{2}\bigr]
\;\le\;
\frac{2\bigl(f(w_{0})-f^{\star}\bigr)}{\eta_{\max}T}
\;+\;
\frac{L\eta_{\max}\sigma^{2}}{2}.
\tag{1}
\]
Consequently, if $\eta_{\max}=c/\sqrt{T}$ for a constant $c>0$, the bound becomes
\[
\EE\!\bigl[\norm{\nabla f(w_{\tau})}^{2}\bigr]
\;=\;O\!\Bigl(\frac{1}{\sqrt{T}}\Bigr).
\]
\end{theorem}

\section*{Theoretical Properties}
\begin{itemize}[leftmargin=*]
\item \textbf{Stability.} The cosine annealing never yields a negative step size; the bound \eqref{thm:main} shows that the algorithm remains stable provided $\eta_{\max}\le \frac{2}{L}$ (so that the descent term dominates the smoothness term).
\item \textbf{Sensitivity to $M$.} The average learning rate over a cycle is $\eta_{\max}/2$, independent of $M$. Larger $M$ yields slower decay within a cycle, which empirically improves exploration; the theorem is agnostic to $M$ because only the average matters.
\item \textbf{Comparison to plain SGD.} For constant step size $\eta$, classic SGD obtains $\EE\!\bigl[\norm{\nabla f(w_{\tau})}^{2}\bigr]\le\frac{2(f(w_{0})-f^{\star})}{\eta T}+L\eta\sigma^{2}$. SGDR replaces $\eta$ by its average $\eta_{\max}/2$, thus enjoys the same $O(1/\sqrt{T})$ rate while periodically resetting the step size, which can help escape shallow local minima.
\end{itemize}

\section*{Discussion}
The theorem shows that warm restarts do not deteriorate the worst‑case convergence guarantee for non‑convex smooth objectives. The bound consists of a deterministic decay term (first term) and a stochastic variance term (second term). By letting $\eta_{\max}=c/\sqrt{T}$ the variance term scales as $O(1/\sqrt{T})$, matching the optimal rate for stochastic first‑order methods under the given assumptions.

